package com.tanmay.vault.service;
import com.fasterxml.jackson.databind.*;import com.tanmay.vault.crypto.CryptoService;import com.tanmay.vault.model.Credential;import com.tanmay.vault.cloud.SupabaseClient;import java.io.*;import java.time.Instant;import java.util.*;import java.nio.file.*;
public final class CredentialService {
 private final CryptoService crypto;private final SupabaseClient cloud;private final String token;private final byte[] key;private final ObjectMapper json=new ObjectMapper();private final Map<UUID,String> records=new LinkedHashMap<>();private final Path cache;
 public CredentialService(CryptoService c,SupabaseClient cloud,String token,byte[] key,Path cache){crypto=c;this.cloud=cloud;this.token=token;this.key=key.clone();this.cache=cache;loadCache();}
 private void loadCache(){if(cache==null||!Files.exists(cache))return;try{for(JsonNode n:json.readTree(Files.readAllBytes(cache)))records.put(UUID.fromString(n.path("id").asText()),n.path("payload").asText());}catch(Exception ignored){records.clear();}}
 private void persist(){if(cache==null)return;try{List<Map<String,String>> rows=new ArrayList<>();records.forEach((id,p)->rows.add(Map.of("id",id.toString(),"payload",p)));Path tmp=cache.resolveSibling(cache.getFileName()+".tmp");Files.write(tmp,json.writeValueAsBytes(rows));try{Files.move(tmp,cache,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(tmp,cache,StandardCopyOption.REPLACE_EXISTING);}}catch(Exception ignored){}}
 public synchronized List<Credential> list(){try{for(var row:cloud.list(token))records.put(row.id,row.encrypted_payload);persist();}catch(IOException ignored){}List<Credential> out=new ArrayList<>();for(String payload:records.values())try{out.add(json.readValue(crypto.decrypt(payload,key),Credential.class));}catch(Exception ignored){}out.sort(Comparator.comparing(Credential::website,String.CASE_INSENSITIVE_ORDER));return out;}
 public synchronized void save(Credential c)throws Exception{InputValidator.validate(c.website(),c.username(),c.password(),c.notes());Credential v=new Credential(c.id(),c.website().trim(),c.username().trim(),c.password(),c.notes()==null?"":c.notes(),Instant.now());String enc=crypto.encrypt(json.writeValueAsString(v),key);cloud.upsert(token,new SupabaseClient.CloudRecord(v.id(),enc,v.updatedAt().toString()));records.put(v.id(),enc);persist();}
 public synchronized void delete(UUID id)throws IOException{cloud.delete(token,id);records.remove(id);persist();}
 public synchronized List<Credential> search(String q){String x=q==null?"":q.toLowerCase(Locale.ROOT);return list().stream().filter(c->c.website().toLowerCase(Locale.ROOT).contains(x)||c.username().toLowerCase(Locale.ROOT).contains(x)).toList();}
}
